window.blogDetail = {"blogId":1599831606,"blogType":0,"pubTime":"2020-09-11 21:40","sLastModifyTime":"2020-09-11 21:51","lastModifyTime":1599832309,"cate":"个人日记","cateHex":"b8f6c8cbc8d5bcc7","title":"我读《红楼梦》（42）第三十七回 秋爽斋偶结海棠社，蘅芜苑夜拟菊花题——诗的品格与人之风韵","commentNum":0,"effect1":66048,"effect2":524294,"ar":0,"block":0,"inproc":false,"appeal":0,"abstract":"“ 诗者，志之所之也，在心为志，发言为诗，情动于中而形于言，言之不足，故嗟叹之，嗟叹之不足，故咏歌之，咏歌之不足，不知手之舞之，足之蹈之也。”诗歌，作为一种古老的文学体裁，起源于人们劳作时的歌咏，是人内心情感和志向的表达。最初，通过和谐整齐的韵律和悠扬的曲调来唤起人们内心的情感共鸣，也就是说，诗最初是乐曲的附庸，因为文字的出现远在语言之后，远古的祖先通过各式各样的声音记录着生活中的悲欢喜乐，所以《...","artype":1,"arUins":"","blogid":1599831606,"voteids":0,"pubtime":1599832309,"replynum":0,"category":"个人日记","effect":66048,"exblogtype":0,"sus_flag":false,"friendrelation":[],"lp_type":0,"lp_id":0,"lp_style":0,"lp_flag":0,"orguin":619774944,"orgblogid":1599831606,"mention_uins":[],"attach":[],"comments":[],"html":"","custom_title":"我读《红楼梦》（42）第三十七回 秋爽斋偶结海棠社，蘅芜苑夜拟菊花题——诗的品格与人之风韵","custom_html":"","uniKey":"http://user.qzone.qq.com/619774944/blog/1599831606"}